export const healthcareBaselineHtml = "<!-- ===================== HEALTHCARE — SECTION SUB NAV (STICKY TABS) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --tabText:#6B7280;\n    --tabActive: var(--indigo);\n    --line:#E6E8EF;\n    --bg:#ffffff;\n\n    /* ✅ Height of this subnav (kept as a variable for scroll offset) */\n    --secTabsH: 58px;\n  }\n\n  .hcTabs, .hcTabs *{box-sizing:border-box;}\n\n  /* ✅ Sticky subnav only (main header can stay non-sticky) */\n  .hcTabs{\n    position:sticky;\n    top:0;\n    z-index:9999;\n    background:var(--bg);\n    border-bottom:1px solid var(--line);\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    isolation:isolate;\n  }\n\n  .hcTabs__inner{\n    max-width:1200px;\n    margin:0 auto;\n    padding:0 20px;\n    height:var(--secTabsH);\n    display:flex;\n    align-items:center;\n    gap:14px;\n  }\n\n  .hcTabs__label{\n    font-weight:900;\n    letter-spacing:.08em;\n    text-transform:uppercase;\n    color:#111;\n    font-size:12px;\n    padding-right:14px;\n    border-right:1px solid var(--line);\n    margin-right:2px;\n    white-space:nowrap;\n  }\n\n  .hcTabs__list{\n    display:flex;\n    align-items:center;\n    gap:0;\n    flex-wrap:nowrap;\n    overflow:auto;\n    scrollbar-width:none;\n  }\n  .hcTabs__list::-webkit-scrollbar{display:none;}\n\n  .hcTabs__link{\n    position:relative;\n    display:inline-flex;\n    align-items:center;\n    height:var(--secTabsH);\n    padding:0 18px;\n    text-decoration:none;\n    text-transform:uppercase;\n    letter-spacing:.06em;\n    font-size:12px;\n    font-weight:800;\n    color:var(--tabText);\n    white-space:nowrap;\n  }\n\n  /* vertical separators */\n  .hcTabs__link + .hcTabs__link{\n    border-left:1px solid var(--line);\n  }\n\n  /* active underline */\n  .hcTabs__link.is-active{\n    color:var(--tabActive);\n  }\n  .hcTabs__link.is-active::after{\n    content:\"\";\n    position:absolute;\n    left:14px;\n    right:14px;\n    bottom:0;\n    height:3px;\n    background:var(--tabActive);\n    border-radius:999px;\n  }\n\n  .hcTabs__link:hover{ color:#111; }\n\n  /* ✅ Optional: make the section itself \"reserve space\" so anchor jumps never hide behind sticky tabs */\n  /* Add this class to each target section wrapper if you want:\n     <section id=\"...\" class=\"hcAnchorFix\"> ... */\n  .hcAnchorFix{ scroll-margin-top: calc(var(--secTabsH) + 14px); }\n\n  @media(max-width:980px){\n    .hcTabs__inner{padding:0 14px;}\n    .hcTabs__label{display:none;}\n    .hcTabs__link{padding:0 14px;}\n  }\n</style>\n\n<nav class=\"hcTabs\" aria-label=\"Healthcare page navigation\">\n  <div class=\"hcTabs__inner\">\n    <div class=\"hcTabs__label\">HEALTHCARE</div>\n\n    <div class=\"hcTabs__list\">\n      <!-- ✅ Update IDs to match your section IDs -->\n      <a class=\"hcTabs__link is-active\" href=\"#hc-hero\">Overview</a>\n      <a class=\"hcTabs__link\" href=\"#hc-context\">Context</a>\n      <a class=\"hcTabs__link\" href=\"#healthcare-challenges\">Key Challenges</a>\n      <a class=\"hcTabs__link\" href=\"#why-healthcare-us\">Why Us</a>\n\n    </div>\n  </div>\n</nav>\n\n<script>\n(function(){\n  const nav = document.querySelector('.hcTabs');\n  if(!nav) return;\n\n  const links = Array.from(nav.querySelectorAll('.hcTabs__link'));\n  const getOffset = () => {\n    const h = nav.getBoundingClientRect().height || 58;\n    return h + 12; // ✅ small breathing space so title is visible\n  };\n\n  // Smooth scroll with correct offset so sections are NOT hidden under sticky tabs\n  links.forEach(a=>{\n    a.addEventListener('click', (e)=>{\n      const href = a.getAttribute('href');\n      if(!href || !href.startsWith('#')) return;\n\n      const el = document.querySelector(href);\n      if(!el) return;\n\n      e.preventDefault();\n      const y = el.getBoundingClientRect().top + window.pageYOffset - getOffset();\n      window.scrollTo({ top:y, behavior:'smooth' });\n      history.replaceState(null, '', href);\n    });\n  });\n\n  // Active state on scroll\n  const targets = links\n    .map(a => document.querySelector(a.getAttribute('href')))\n    .filter(Boolean);\n\n  const setActive = (id) => {\n    links.forEach(a=>{\n      a.classList.toggle('is-active', a.getAttribute('href') === '#'+id);\n    });\n  };\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  if(isElementor) return;\n  if(!('IntersectionObserver' in window)) return;\n\n  const io = new IntersectionObserver((entries)=>{\n    // pick the entry closest to top that is visible\n    const visible = entries\n      .filter(e=>e.isIntersecting)\n      .sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];\n\n    if(visible && visible.target && visible.target.id){\n      setActive(visible.target.id);\n    }\n  }, { root:null, threshold:[0.2,0.35,0.5,0.65] });\n\n  targets.forEach(t=>{\n    if(t.id) io.observe(t);\n  });\n})();\n</script>\n\n<!-- ===================== HEALTHCARE — HERO + INTRO (WHITE then PREMIUM BG) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    /* ✅ ONLY the 4 agreed brand colours */\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    /* neutrals */\n    --ink:#0B0F1A;\n    --muted:#3C4160;\n    --line:rgba(49,59,134,.16);\n    --white:#ffffff;\n  }\n\n  .hc-hero, .hc-hero *{box-sizing:border-box;}\n  .hc-hero{\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    background:var(--white); /* ✅ start with white */\n    padding:86px 20px 34px;\n  }\n\n  .hc-hero__inner{\n    max-width:1200px;\n    margin:0 auto;\n    display:grid;\n    grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);\n    gap:44px;\n    align-items:center;\n  }\n\n  .hc-hero__kicker{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:700;\n    margin:0 0 12px;\n  }\n\n  .hc-hero__title{\n    margin:0 0 14px;\n    font-size:clamp(34px,4.2vw,56px);\n    line-height:1.08;\n    font-weight:800;\n    color:var(--navy);\n  }\n\n  .hc-hero__subtitle{\n    margin:0 0 14px;\n    font-size:clamp(16px,2vw,20px);\n    line-height:1.55;\n    font-weight:600;\n    color:var(--indigo);\n    max-width:860px;\n  }\n\n  .hc-hero__p{\n    margin:0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:var(--muted);\n    max-width:900px;\n  }\n  .hc-hero__p + .hc-hero__p{ margin-top:14px; }\n\n  /* Right visual (VIDEO) */\n  .hc-hero__visual{\n    border:1px solid var(--line);\n    border-radius:22px;\n    background:#fff;\n    overflow:hidden;\n    min-height:320px;\n    position:relative;\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n  }\n\n  .hc-hero__video{\n    width:100%;\n    height:100%;\n    min-height:320px;\n    display:block;\n    object-fit:cover; /* ✅ fills the frame */\n    background:#0b0f1a;\n  }\n\n  /* subtle overlay to keep it premium */\n  .hc-hero__visual::after{\n    content:\"\";\n    position:absolute;\n    inset:0;\n    pointer-events:none;\n    background:\n      radial-gradient(circle at 18% 12%, rgba(98,90,216,.18), transparent 55%),\n      radial-gradient(circle at 90% 20%, rgba(31,156,228,.14), transparent 55%),\n      linear-gradient(180deg, rgba(2,12,79,.10), rgba(2,12,79,0));\n    opacity:.55;\n    mix-blend-mode:multiply;\n  }\n\n  /* small badge (optional) */\n  .hc-hero__badge{\n    position:absolute;\n    left:18px;\n    top:18px;\n    display:inline-flex;\n    align-items:center;\n    gap:10px;\n    padding:10px 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.18);\n    background:rgba(255,255,255,.74);\n    backdrop-filter:blur(8px);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:700;\n    z-index:2;\n  }\n  .hc-hero__dot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(98,90,216,.12);\n  }\n\n  /* PREMIUM BACKGROUND INTRO STRIP */\n  .hc-intro, .hc-intro *{box-sizing:border-box;}\n  .hc-intro{\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    padding:28px 20px 86px;\n    background:\n      radial-gradient(circle at 18% 0%, rgba(98,90,216,.08), transparent 55%),\n      radial-gradient(circle at 95% 30%, rgba(49,59,134,.08), transparent 55%),\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\n      rgba(49,59,134,.03);\n  }\n  .hc-intro__inner{\n    max-width:1200px;\n    margin:0 auto;\n  }\n\n  .hc-intro__card{\n    border:1px solid rgba(49,59,134,.16);\n    border-radius:22px;\n    background:rgba(255,255,255,.90);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    padding:22px 22px;\n  }\n\n  .hc-intro__text{\n    margin:0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:var(--muted);\n    max-width:1050px;\n  }\n\n  @media (max-width:980px){\n    .hc-hero{ padding:74px 18px 24px; }\n    .hc-hero__inner{ grid-template-columns:1fr; gap:22px; }\n    .hc-hero__visual{ min-height:240px; }\n    .hc-hero__video{ min-height:240px; }\n    .hc-intro{ padding:18px 18px 74px; }\n  }\n</style>\n\n<!-- WHITE HERO -->\n<section class=\"hc-hero\" id=\"hc-hero\">\n  <div class=\"hc-hero__inner\">\n\n    <!-- LEFT CONTENT (your content) -->\n    <div>\n      <div class=\"hc-hero__kicker\">Healthcare Sector – Industry Solutions &amp; Transformation Services</div>\n\n      <h1 class=\"hc-hero__title\">Transforming Healthcare Enterprises for Quality, Access, and Sustainable Performance</h1>\n\n      <p class=\"hc-hero__p\">\n        The Healthcare sector is under unprecedented pressure—rising demand, constrained capacity, increasing cost of care, workforce shortages, regulatory complexity, and rapidly evolving patient expectations.\n        At the same time, healthcare organisations are expected to deliver better outcomes, safer care, and greater access, often with limited resources and growing scrutiny.\n      </p>\n    </div>\n\n    <!-- RIGHT VISUAL (VIDEO) -->\n    <div class=\"hc-hero__visual\">\n      <div class=\"hc-hero__badge\"><span class=\"hc-hero__dot\" aria-hidden=\"true\"></span> Healthcare Transformation</div>\n\n      <!-- ✅ CHANGE VIDEO URL HERE -->\n      <video class=\"hc-hero__video\"\n             autoplay\n             muted\n             loop\n             playsinline\n             controls\n             poster=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\">\n        <!-- Replace this with your video file URL later -->\n        <source src=\"YOUR-VIDEO-URL.mp4\" type=\"video/mp4\">\n      </video>\n    </div>\n\n  </div>\n</section>\n\n\n</section>\n\n\n\n\n<section class=\"hc-intro\" id=\"hc-context\">\n  <div class=\"hc-intro__inner\">\n    <div class=\"hc-intro__card\">\n      <p class=\"hc-intro__text\">\n        At <strong>[Your Firm Name]</strong>, we partner with pharmaceutical companies to convert complexity into clarity and strategy into measurable outcomes. Our integrated approach—spanning strategy, operations, digital, ESG, and capability building—helps pharma organisations accelerate growth, build resilient operations, and deliver world-class quality.\n      </p>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== HEALTHCARE — KEY CHALLENGES (DESKTOP: LIST + DETAIL | MOBILE: CARD ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#4B5168;\n    --line:rgba(49,59,134,.16);\n    --card:#fff;\n  }\n\n  .hcK, .hcK *{ box-sizing:border-box; }\n\n  .hcK{\n    position:relative;\n    padding:92px 20px;\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    overflow:hidden;\n    background:\n      radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 95% 30%, rgba(49,59,134,.10), transparent 55%),\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n      rgba(49,59,134,.03);\n  }\n\n  .hcK__inner{ max-width:1200px; margin:0 auto; position:relative; }\n\n  .hcK__top{\n    display:grid;\n    grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);\n    gap:32px;\n    align-items:start;\n    margin-bottom:22px;\n  }\n\n  .hcK__eyebrow{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n    margin:0 0 10px;\n  }\n\n  .hcK__title{\n    margin:0;\n    font-size:clamp(38px,4.4vw,56px);\n    line-height:1.05;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .hcK__intro{\n    margin:22px 0 0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:#3C4160;\n    max-width:720px;\n  }\n\n  .hcK__grid{\n    display:grid;\n    grid-template-columns:minmax(0,.86fr) minmax(0,1.14fr);\n    gap:26px;\n    align-items:stretch;\n    margin-top:18px;\n  }\n\n  /* LEFT RAIL (desktop/tablet) */\n  .hcK__rail{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.78);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    min-width:0;\n  }\n\n  .hcK__railTop{\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:14px;\n    padding:16px 16px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n  }\n\n  .hcK__railLabel{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--navy);\n    font-weight:900;\n  }\n\n  .hcK__railPill{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:32px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.85);\n    font-size:12px;\n    font-weight:800;\n    color:var(--indigo);\n    white-space:nowrap;\n  }\n  .hcK__railPillDot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.10);\n  }\n\n  .hcK__item{\n    width:100%;\n    display:grid;\n    grid-template-columns:44px 1fr;\n    gap:12px;\n    align-items:center;\n    padding:14px 16px;\n    background:transparent;\n    border:0;\n    border-top:1px solid rgba(49,59,134,.10);\n    cursor:pointer;\n    text-align:left;\n    transition:background .18s ease;\n    min-width:0;\n  }\n  .hcK__item:first-of-type{ border-top:0; }\n  .hcK__item:hover{ background:rgba(49,59,134,.03); }\n\n  .hcK__icon{\n    width:40px;height:40px;\n    border-radius:14px;\n    display:grid;\n    place-items:center;\n    background:rgba(49,59,134,.05);\n    border:1px solid rgba(49,59,134,.14);\n    font-size:16px;\n  }\n\n  .hcK__itemTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    color:var(--navy);\n    line-height:1.25;\n  }\n\n  /* ✅ 2-line preview enforced */\n  .hcK__itemPreview{\n    margin:4px 0 0;\n    font-size:13px;\n    line-height:1.5;\n    color:#5B6282;\n\n    display:-webkit-box !important;\n    -webkit-box-orient:vertical !important;\n    -webkit-line-clamp:2 !important;\n    overflow:hidden !important;\n    text-overflow:ellipsis !important;\n    white-space:normal !important;\n    overflow-wrap:anywhere;\n    min-width:0;\n    max-width:100%;\n  }\n\n  /* Accordion content hidden by default (desktop/tablet) */\n  .hcK__acc{ display:none; }\n\n  .hcK__item[aria-selected=\"true\"]{\n    background:rgba(31,156,228,.06);\n    position:relative;\n  }\n  .hcK__item[aria-selected=\"true\"]::before{\n    content:\"\";\n    position:absolute;\n    left:0; top:0; bottom:0;\n    width:4px;\n    background:linear-gradient(180deg,var(--accent),var(--violet));\n  }\n  .hcK__item[aria-selected=\"true\"] .hcK__icon{\n    border-color:rgba(31,156,228,.28);\n    background:rgba(31,156,228,.08);\n  }\n\n  /* RIGHT PANEL (desktop/tablet) */\n  .hcK__panel{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.86);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    display:flex;\n    flex-direction:column;\n    min-width:0;\n    min-height:520px;\n  }\n\n  .hcK__panelHead{\n    padding:16px 18px 14px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 60%),\n      rgba(255,255,255,.85);\n  }\n\n  .hcK__panelKicker{\n    margin:0 0 6px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .hcK__panelTitle{\n    margin:0;\n    font-size:22px;\n    line-height:1.25;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .hcK__panelBody{ padding:18px; flex:1 1 auto; }\n\n  .hcK__bullets{\n    margin:0;\n    padding:0;\n    list-style:none;\n    display:grid;\n    gap:12px;\n  }\n\n  .hcK__bullets li{\n    display:flex;\n    gap:10px;\n    align-items:flex-start;\n    font-size:14.5px;\n    line-height:1.65;\n    color:#2E334D;\n  }\n\n  .hcK__dot{\n    width:10px;height:10px;border-radius:999px;\n    margin-top:7px;\n    flex:0 0 auto;\n    background:rgba(31,156,228,.22);\n    outline:3px solid rgba(31,156,228,.10);\n  }\n\n  .hcK__panelFooter{\n    padding:14px 16px;\n    border-top:1px solid rgba(49,59,134,.12);\n    background:rgba(255,255,255,.75);\n    display:flex;\n    flex-wrap:wrap;\n    gap:10px;\n  }\n\n  .hcK__chip{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:34px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.9);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:800;\n  }\n  .hcK__chip i{\n    width:7px;height:7px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    display:inline-block;\n  }\n\n  .hcK__fade{\n    opacity:1;\n    transform:translateY(0);\n    transition:opacity .18s ease, transform .18s ease;\n  }\n  .hcK__fade.is-switching{\n    opacity:0;\n    transform:translateY(6px);\n  }\n\n  @media (max-width:1024px){\n    .hcK{ padding:78px 18px; }\n    .hcK__top{ grid-template-columns:1fr; gap:14px; }\n    .hcK__intro{ margin-top:0; }\n    .hcK__grid{ grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr); gap:18px; }\n    .hcK__panel{ min-height:unset; }\n  }\n\n  /* ===================== MOBILE: convert to nice stacked card accordion ===================== */\n  @media (max-width:820px){\n    .hcK{ padding:70px 16px; }\n    .hcK__title{ font-size:clamp(30px,9vw,40px); }\n    .hcK__intro{ font-size:14.8px; margin-top:10px; }\n\n    .hcK__grid{ grid-template-columns:1fr; }\n\n    /* Hide the right panel on mobile */\n    .hcK__panel{ display:none !important; }\n\n    /* Remove the big “rail frame” on mobile */\n    .hcK__rail{\n      border:none;\n      background:transparent;\n      backdrop-filter:none;\n      box-shadow:none;\n      overflow:visible;            /* ✅ important */\n    }\n\n    /* Keep a small header pill bar */\n    .hcK__railTop{\n      padding:14px 14px;\n      border:1px solid rgba(49,59,134,.16);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 10px 26px rgba(0,0,0,.06);\n      margin-bottom:12px;\n    }\n\n    /* Each item becomes its own card */\n    .hcK__item{\n      border:1px solid rgba(49,59,134,.14);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 12px 28px rgba(0,0,0,.06);\n      margin:0 0 12px;\n      padding:14px 14px;\n      grid-template-columns:42px 1fr;\n      align-items:start;\n    }\n    .hcK__item:first-of-type{ border-top:1px solid rgba(49,59,134,.14); }\n\n    .hcK__icon{ width:38px;height:38px; border-radius:14px; margin-top:2px; }\n\n    /* Accordion body: clean and roomy */\n    .hcK__acc{\n      grid-column:1 / -1;\n      margin:10px 0 2px;\n      padding:12px 12px;\n      border-radius:16px;\n      border:1px solid rgba(49,59,134,.12);\n      background:rgba(49,59,134,.03);\n      display:none;\n    }\n    .hcK__item[aria-expanded=\"true\"] .hcK__acc{ display:block; }\n\n    .hcK__accBullets{\n      margin:0;\n      padding:0;\n      list-style:none;\n      display:grid;\n      gap:10px;\n    }\n    .hcK__accBullets li{\n      display:flex;\n      gap:10px;\n      align-items:flex-start;\n      font-size:14px;\n      line-height:1.65;\n      color:#2E334D;\n    }\n\n    .hcK__accChips{\n      margin-top:12px;\n      display:flex;\n      flex-wrap:wrap;\n      gap:10px;\n    }\n\n    /* Chips smaller on mobile */\n    .hcK__chip{ height:32px; font-size:12px; padding:0 11px; }\n  }\n  \n  /* ===================== FORCE MOBILE LAYOUT VIA CLASS (works in Elementor preview too) ===================== */\n.hcK.is-mobile{\n  padding:70px 16px !important;\n}\n\n.hcK.is-mobile .hcK__grid{\n  grid-template-columns:1fr !important;\n}\n\n.hcK.is-mobile .hcK__panel{\n  display:none !important;\n}\n\n/* remove the “big framed rail” */\n.hcK.is-mobile .hcK__rail{\n  border:none !important;\n  background:transparent !important;\n  box-shadow:none !important;\n  backdrop-filter:none !important;\n  overflow:visible !important;\n}\n\n/* keep header as a small bar */\n.hcK.is-mobile .hcK__railTop{\n  padding:14px 14px !important;\n  border:1px solid rgba(49,59,134,.14) !important;\n  border-radius:16px !important;\n  background:#fff !important;\n  box-shadow:0 10px 24px rgba(0,0,0,.06) !important;\n  margin-bottom:12px !important;\n}\n\n/* each item is a separate card */\n.hcK.is-mobile .hcK__item{\n  border:1px solid rgba(49,59,134,.12) !important;\n  border-radius:16px !important;\n  background:#fff !important;\n  box-shadow:0 12px 26px rgba(0,0,0,.06) !important;\n  margin:0 0 12px !important;\n  padding:14px 14px !important;\n  grid-template-columns:42px 1fr !important;\n  align-items:start !important;\n}\n\n/* ✅ kill the desktop selected left bar on mobile */\n.hcK.is-mobile .hcK__item[aria-selected=\"true\"]::before{\n  display:none !important;\n}\n\n/* ✅ no huge blue “selected” wash */\n.hcK.is-mobile .hcK__item[aria-selected=\"true\"]{\n  background:#fff !important;\n}\n\n/* accordion area: simple + readable (no big tinted slab) */\n.hcK.is-mobile .hcK__acc{\n  display:none;\n  grid-column:1 / -1;\n  margin:10px 0 0;\n  padding:12px 12px;\n  border-radius:14px;\n  border:1px solid rgba(49,59,134,.10);\n  background:rgba(49,59,134,.02);\n}\n\n.hcK.is-mobile .hcK__item[aria-expanded=\"true\"] .hcK__acc{\n  display:block !important;\n}\n\n/* chips wrap nicely */\n.hcK.is-mobile .hcK__chip{\n  height:32px !important;\n  font-size:12px !important;\n  padding:0 11px !important;\n}\n\n/* hard override to prevent desktop selected styling on mobile */\n.hcK.is-mobile .hcK__item[aria-selected=\"true\"]{\n  background:#fff !important;\n}\n.hcK.is-mobile .hcK__item[aria-selected=\"true\"]::before{\n  display:none !important;\n}\n\n\n/* ✅ MOBILE OVERFLOW FIX: force bullet text to wrap inside the accordion card */\n@media (max-width:820px){\n\n  /* ensure the accordion box itself never lets content spill */\n  .hcK__acc{\n    overflow:hidden !important;\n  }\n\n  /* allow flex children to shrink */\n  .hcK__accBullets li{\n    min-width:0 !important;\n  }\n\n  /* THIS is the key: the text span must be allowed to shrink + wrap */\n  .hcK__accBullets li span:last-child{\n    min-width:0 !important;\n    max-width:100% !important;\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n    white-space:normal !important;\n  }\n\n  /* also protect the preview line if any long word appears */\n  .hcK__itemPreview{\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n  }\n}\n\n/* ✅ HARD FIX: bullet text wrapping on mobile (prevents right-side clipping) */\n@media (max-width: 820px){\n\n  /* protect the card itself */\n  .hcK__item,\n  .hcK__acc,\n  .hcK__accBullets{\n    max-width: 100% !important;\n    min-width: 0 !important;\n  }\n\n  /* bullet row must be allowed to wrap */\n  .hcK__accBullets li{\n    display:flex !important;\n    align-items:flex-start !important;\n    gap:10px !important;\n    flex-wrap:wrap !important;      /* ✅ key */\n    min-width:0 !important;\n    max-width:100% !important;\n  }\n\n  /* dot stays fixed */\n  .hcK__accBullets li .hcK__dot{\n    flex:0 0 auto !important;\n  }\n\n  /* text must become the flexible column */\n  .hcK__accBullets li span:last-child{\n    flex: 1 1 0% !important;        /* ✅ key */\n    min-width:0 !important;\n    max-width:100% !important;\n    display:block !important;\n    white-space:normal !important;\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n  }\n}\n\n/* ✅ CRITICAL: force wrapping inside the button (Elementor/theme often sets button nowrap) */\n.hcK__item{\n  white-space: normal !important;\n}\n\n/* ✅ allow the text column to shrink & wrap (grid child must have min-width:0) */\n.hcK__item > div:nth-child(2){\n  min-width: 0 !important;\n}\n\n/* ✅ titles + preview must wrap (not clip) */\n.hcK__itemTitle,\n.hcK__itemPreview{\n  white-space: normal !important;\n  overflow-wrap: anywhere !important;\n  word-break: break-word !important;\n  max-width: 100% !important;\n}\n\n/* ✅ extra safety on mobile */\n@media (max-width: 820px){\n  .hcK__rail{ overflow: visible !important; } /* prevent rail clipping on small screens */\n  .hcK__item{ max-width: 100% !important; }\n}\n\n\n</style>\n\n\n\n<section class=\"hcK\" id=\"healthcare-challenges\">\n  <div class=\"hcK__inner\">\n\n    <div class=\"hcK__top\">\n      <div>\n        <p class=\"hcK__eyebrow\">Healthcare Sector</p>\n        <h2 class=\"hcK__title\">Key Challenges</h2>\n      </div>\n\n      <p class=\"hcK__intro\">\n        Healthcare organisations are expected to deliver better outcomes, safer care, and greater access—often with\n        limited resources and growing scrutiny. Here are the critical pressure points we help solve.\n      </p>\n    </div>\n\n    <div class=\"hcK__grid\">\n\n      <div class=\"hcK__rail\" role=\"tablist\" aria-label=\"Healthcare challenges list\">\n        <div class=\"hcK__railTop\">\n          <div class=\"hcK__railLabel\">Challenges</div>\n          <div class=\"hcK__railPill\"><span class=\"hcK__railPillDot\" aria-hidden=\"true\"></span>Executive view</div>\n        </div>\n\n        <button class=\"hcK__item\" role=\"tab\" aria-selected=\"true\" aria-expanded=\"false\" data-key=\"c1\">\n          <div class=\"hcK__icon\">🏥</div>\n          <div>\n            <p class=\"hcK__itemTitle\">Access, Growth &amp; Demand Pressure</p>\n            <p class=\"hcK__itemPreview\">Rapidly growing demand, capacity constraints, uneven access to quality care, and limited service visibility.</p>\n          </div>\n          <div class=\"hcK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"hcK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c2\">\n          <div class=\"hcK__icon\">⏱️</div>\n          <div>\n            <p class=\"hcK__itemTitle\">Operational Inefficiencies &amp; Cost Pressures</p>\n            <p class=\"hcK__itemPreview\">Fragmented delivery, long wait times, heavy administrative burden, manual processes, and rising operating costs.</p>\n          </div>\n          <div class=\"hcK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"hcK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c3\">\n          <div class=\"hcK__icon\">🛡️</div>\n          <div>\n            <p class=\"hcK__itemTitle\">Quality, Safety &amp; Outcome Variability</p>\n            <p class=\"hcK__itemPreview\">Inconsistent outcomes, adverse events and readmissions, limited real-time indicators, and difficulty standardising pathways.</p>\n          </div>\n          <div class=\"hcK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"hcK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c4\">\n          <div class=\"hcK__icon\">👩‍⚕️</div>\n          <div>\n            <p class=\"hcK__itemTitle\">Workforce &amp; Capability Challenges</p>\n            <p class=\"hcK__itemPreview\">Shortages, burnout from workload and documentation, capability depth gaps, and resistance to operational change.</p>\n          </div>\n          <div class=\"hcK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"hcK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c5\">\n          <div class=\"hcK__icon\">📊</div>\n          <div>\n            <p class=\"hcK__itemTitle\">Digital, Data &amp; Technology Gaps</p>\n            <p class=\"hcK__itemPreview\">Disconnected systems, underused data, slow automation and analytics adoption, and responsible scaling of AI initiatives.</p>\n          </div>\n          <div class=\"hcK__acc\" aria-hidden=\"true\"></div>\n        </button>\n      </div>\n\n      <!-- Desktop panel only -->\n      <aside class=\"hcK__panel\" role=\"tabpanel\" aria-live=\"polite\">\n        <div class=\"hcK__fade\" id=\"hcK-fade\">\n          <div class=\"hcK__panelHead\">\n            <p class=\"hcK__panelKicker\">Challenge Focus</p>\n            <h3 class=\"hcK__panelTitle\" id=\"hcK-title\">Access, Growth &amp; Demand Pressure</h3>\n          </div>\n\n          <div class=\"hcK__panelBody\">\n            <ul class=\"hcK__bullets\" id=\"hcK-bullets\"></ul>\n          </div>\n\n          <div class=\"hcK__panelFooter\" id=\"hcK-chips\"></div>\n        </div>\n      </aside>\n\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const data = {\n    c1:{\n      title:\"Access, Growth & Demand Pressure\",\n      bullets:[\n        \"Rapidly growing patient demand and ageing populations\",\n        \"Capacity constraints across hospitals, clinics, and diagnostics\",\n        \"Uneven access to quality care across regions\",\n        \"Limited visibility into service demand and growth opportunities\"\n      ],\n      chips:[\"Capacity planning\",\"Access expansion\",\"Demand visibility\"]\n    },\n    c2:{\n      title:\"Operational Inefficiencies & Cost Pressures\",\n      bullets:[\n        \"Fragmented care delivery across departments and facilities\",\n        \"Long patient wait times and inefficient patient flow\",\n        \"High administrative burden and manual processes\",\n        \"Rising operating costs with pressure on margins\"\n      ],\n      chips:[\"Patient flow\",\"Cost control\",\"Admin simplification\"]\n    },\n    c3:{\n      title:\"Quality, Safety & Outcome Variability\",\n      bullets:[\n        \"Inconsistent clinical processes and outcomes\",\n        \"High cost of adverse events, rework, and readmissions\",\n        \"Limited real-time visibility into quality and safety indicators\",\n        \"Challenges in standardising care pathways\"\n      ],\n      chips:[\"Care pathways\",\"Safety metrics\",\"Outcome reliability\"]\n    },\n    c4:{\n      title:\"Workforce & Capability Challenges\",\n      bullets:[\n        \"Shortage of skilled clinicians and frontline staff\",\n        \"Burnout driven by workload, inefficiency, and documentation burden\",\n        \"Limited leadership and operational capability depth\",\n        \"Resistance to change across clinical and non-clinical teams\"\n      ],\n      chips:[\"Workforce capacity\",\"Burnout reduction\",\"Change adoption\"]\n    },\n    c5:{\n      title:\"Digital, Data & Technology Gaps\",\n      bullets:[\n        \"Disconnected systems across clinical, administrative, and financial domains\",\n        \"Underutilisation of data for decision-making and population health\",\n        \"Slow adoption of automation and analytics\",\n        \"Challenges in scaling digital health and AI initiatives responsibly\"\n      ],\n      chips:[\"Interoperability\",\"Analytics\",\"Responsible AI\"]\n    }\n  };\n\n  const root = document.querySelector('#healthcare-challenges');\n  if(!root) return;\n  \n  function applyMobileClass(){\n  const mqMobile = window.matchMedia && window.matchMedia('(max-width: 820px)').matches;\n\n  // Elementor preview helpers (these classes appear in Elementor responsive modes)\n  const elMobile =\n    document.body.classList.contains('elementor-device-mobile') ||\n    document.body.classList.contains('e--ua-device-mobile');\n\n  const mobile = mqMobile || elMobile;\n\n  root.classList.toggle('is-mobile', mobile);\n  return mobile;\n}\nconst isNowMobile = applyMobileClass();\nwindow.addEventListener('resize', applyMobileClass);\n\n\n  const tabs = Array.from(root.querySelectorAll('.hcK__item'));\n  const fade = root.querySelector('#hcK-fade');\n  const title = root.querySelector('#hcK-title');\n  const bullets = root.querySelector('#hcK-bullets');\n  const chips = root.querySelector('#hcK-chips');\n\n  function isMobile(){\n    return window.matchMedia && window.matchMedia('(max-width: 820px)').matches;\n  }\n\n  function renderDesktop(key){\n    const d = data[key];\n    if(!d || !fade) return;\n\n    fade.classList.add('is-switching');\n    setTimeout(()=>{\n      title.textContent = d.title;\n\n      bullets.innerHTML = d.bullets.map(x =>\n        `<li><span class=\"hcK__dot\"></span><span>${x}</span></li>`\n      ).join('');\n\n      chips.innerHTML = d.chips.map(x =>\n        `<span class=\"hcK__chip\"><i></i>${x}</span>`\n      ).join('');\n\n      fade.classList.remove('is-switching');\n    }, 160);\n  }\n\n  function renderAccordionItem(btn){\n    const key = btn.dataset.key;\n    const d = data[key];\n    if(!d) return;\n\n    const acc = btn.querySelector('.hcK__acc');\n    if(!acc) return;\n\n    acc.innerHTML = `\n      <ul class=\"hcK__accBullets\">\n        ${d.bullets.map(x => `<li><span class=\"hcK__dot\"></span><span>${x}</span></li>`).join('')}\n      </ul>\n      <div class=\"hcK__accChips\">\n        ${d.chips.map(x => `<span class=\"hcK__chip\"><i></i>${x}</span>`).join('')}\n      </div>\n    `;\n  }\n\n  tabs.forEach(btn => renderAccordionItem(btn));\n\n  function setActive(btn){\n    tabs.forEach(x=>{\n      x.setAttribute('aria-selected','false');\n      x.setAttribute('aria-expanded','false');\n    });\n    btn.setAttribute('aria-selected','true');\n\n    if(isMobile()){\n      btn.setAttribute('aria-expanded','true');\n    }else{\n      btn.setAttribute('aria-expanded','false');\n      renderDesktop(btn.dataset.key);\n    }\n  }\n\n  // Desktop starts with first selected\n  renderDesktop('c1');\n\n  // Mobile: open the first card by default (so it doesn't look broken)\nif(isMobile() || root.classList.contains('is-mobile')){\n  tabs.forEach(x=>{\n    x.setAttribute('aria-selected','false');\n    x.setAttribute('aria-expanded','false');\n  });\n  tabs[0].setAttribute('aria-selected','true');\n  tabs[0].setAttribute('aria-expanded','true'); // ✅ show accordion content\n}\n\n\n  tabs.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      if(isMobile()){\n        const expanded = btn.getAttribute('aria-expanded') === 'true';\n        // close if already open\n        if(expanded){\n          btn.setAttribute('aria-expanded','false');\n          return;\n        }\n        // open this + close others\n        tabs.forEach(x=>x.setAttribute('aria-expanded','false'));\n        btn.setAttribute('aria-expanded','true');\n        tabs.forEach(x=>x.setAttribute('aria-selected','false'));\n        btn.setAttribute('aria-selected','true');\n      }else{\n        setActive(btn);\n      }\n    });\n  });\n\n  window.addEventListener('resize', ()=>{\n    const active = tabs.find(x => x.getAttribute('aria-selected') === 'true') || tabs[0];\n    if(!isMobile()){\n      renderDesktop(active.dataset.key || 'c1');\n    }\n  });\n})();\n</script>\n\n<!-- ===================== HEALTHCARE — WHY ORGS WORK WITH US (WHITE / PREMIUM) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n\n<style>\n:root{\n  /* Brand colours */\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#4B5168;\n  --line:rgba(49,59,134,.16);\n  --soft:rgba(49,59,134,.04);\n  --white:#ffffff;\n}\n\n/* SECTION */\n.hcWhy, .hcWhy *{box-sizing:border-box;}\n.hcWhy{\n  position:relative;\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:#fff;\n  color:var(--ink);\n  overflow:hidden;\n}\n\n/* subtle premium background detail (very light) */\n.hcWhy::before{\n  content:\"\";\n  position:absolute;\n  inset:-240px -120px auto -120px;\n  height:520px;\n  pointer-events:none;\n  opacity:.9;\n  background:\n    radial-gradient(circle at 20% 35%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 75% 20%, rgba(31,156,228,.10), transparent 55%),\n    radial-gradient(circle at 55% 80%, rgba(2,12,79,.06), transparent 60%);\n}\n\n.hcWhy__inner{\n  max-width:1200px;\n  margin:0 auto;\n  position:relative;\n}\n\n/* GRID */\n.hcWhy__grid{\n  display:grid;\n  grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);\n  gap:54px;\n  align-items:start;\n}\n\n/* LEFT */\n.hcWhy__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.hcWhy__title{\n  margin:0 0 14px;\n  font-size:clamp(32px,3.6vw,46px);\n  line-height:1.12;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.hcWhy__lead{\n  margin:0;\n  font-size:16px;\n  line-height:1.75;\n  color:var(--muted);\n  max-width:560px;\n}\n\n.hcWhy__divider{\n  margin:22px 0 0;\n  width:100%;\n  height:1px;\n  background:linear-gradient(90deg, rgba(49,59,134,.18), rgba(49,59,134,0));\n}\n\n/* RIGHT: “proof stack” (not boring cards) */\n.hcWhy__stack{\n  border:1px solid rgba(49,59,134,.16);\n  border-radius:22px;\n  overflow:hidden;\n  background:rgba(255,255,255,.9);\n  box-shadow:0 18px 46px rgba(0,0,0,.06);\n}\n\n.hcWhy__row{\n  display:grid;\n  grid-template-columns:52px 1fr;\n  gap:14px;\n  padding:18px 18px;\n  border-top:1px solid rgba(49,59,134,.10);\n  background:linear-gradient(180deg, #fff, rgba(49,59,134,.015));\n  transition:background .18s ease, transform .18s ease;\n}\n.hcWhy__row:first-child{ border-top:0; }\n.hcWhy__row:hover{\n  background:linear-gradient(180deg, rgba(31,156,228,.06), rgba(98,90,216,.04));\n}\n\n.hcWhy__icon{\n  width:44px;height:44px;\n  border-radius:16px;\n  display:grid;\n  place-items:center;\n  border:1px solid rgba(49,59,134,.16);\n  background:rgba(49,59,134,.04);\n  position:relative;\n}\n\n.hcWhy__icon::before{\n  content:\"\";\n  width:12px;height:12px;border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.10);\n}\n\n.hcWhy__h{\n  margin:0;\n  font-size:15px;\n  line-height:1.25;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.hcWhy__p{\n  margin:6px 0 0;\n  font-size:14.5px;\n  line-height:1.65;\n  color:#2E334D;\n}\n\n/* bottom highlight band */\n.hcWhy__footer{\n  padding:18px 18px;\n  border-top:1px solid rgba(49,59,134,.10);\n  background:\n    radial-gradient(circle at 0% 0%, rgba(98,90,216,.12), transparent 55%),\n    radial-gradient(circle at 100% 30%, rgba(31,156,228,.10), transparent 60%),\n    rgba(49,59,134,.02);\n}\n\n.hcWhy__footerTitle{\n  margin:0;\n  font-size:14px;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.hcWhy__footerText{\n  margin:8px 0 0;\n  color:#2E334D;\n  font-size:14.5px;\n  line-height:1.65;\n}\n\n/* Responsive */\n@media(max-width:980px){\n  .hcWhy{padding:78px 18px;}\n  .hcWhy__grid{grid-template-columns:1fr; gap:28px;}\n  .hcWhy__lead{max-width:100%;}\n}\n\n@media(max-width:560px){\n  .hcWhy{padding:70px 16px;}\n  .hcWhy__row{grid-template-columns:48px 1fr; padding:16px 14px;}\n  .hcWhy__icon{width:40px;height:40px;border-radius:14px;}\n}\n</style>\n\n<section class=\"hcWhy\" id=\"why-healthcare-us\">\n  <div class=\"hcWhy__inner\">\n\n    <div class=\"hcWhy__grid\">\n\n      <!-- LEFT -->\n      <div>\n        <p class=\"hcWhy__eyebrow\">Why Partner With Us</p>\n        <h2 class=\"hcWhy__title\">Why Healthcare Organisations Work With Us</h2>\n        <p class=\"hcWhy__lead\">\n          We bring disciplined execution, high-reliability thinking, and digital enablement to help healthcare systems\n          improve access, quality, cost, and patient experience—without adding operational complexity.\n        </p>\n        <div class=\"hcWhy__divider\" aria-hidden=\"true\"></div>\n      </div>\n\n      <!-- RIGHT -->\n      <div class=\"hcWhy__stack\">\n\n        <div class=\"hcWhy__row\">\n          <div class=\"hcWhy__icon\" aria-hidden=\"true\"></div>\n          <div>\n            <p class=\"hcWhy__h\">Strategy and Execution as One System</p>\n            <p class=\"hcWhy__p\">We align leadership vision with frontline care delivery.</p>\n          </div>\n        </div>\n\n        <div class=\"hcWhy__row\">\n          <div class=\"hcWhy__icon\" aria-hidden=\"true\"></div>\n          <div>\n            <p class=\"hcWhy__h\">Deep Understanding of High-Reliability Environments</p>\n            <p class=\"hcWhy__p\">Our approaches are designed for patient safety, quality, and regulatory rigour.</p>\n          </div>\n        </div>\n\n        <div class=\"hcWhy__row\">\n          <div class=\"hcWhy__icon\" aria-hidden=\"true\"></div>\n          <div>\n            <p class=\"hcWhy__h\">Digital That Supports Care, Not Complexity</p>\n            <p class=\"hcWhy__p\">Technology implemented to simplify work and enhance judgment.</p>\n          </div>\n        </div>\n\n        <div class=\"hcWhy__row\">\n          <div class=\"hcWhy__icon\" aria-hidden=\"true\"></div>\n          <div>\n            <p class=\"hcWhy__h\">Integrated, Proven Methodologies</p>\n            <p class=\"hcWhy__p\">Strategy, Lean, digital, analytics, TOM, ESG, and change—working together.</p>\n          </div>\n        </div>\n\n        <div class=\"hcWhy__footer\">\n          <p class=\"hcWhy__footerTitle\">Outcome-Driven Engagements</p>\n          <p class=\"hcWhy__footerText\">\n            Every initiative is tied to access, quality, cost, or patient experience.\n          </p>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n</section>\n\n<!-- ===================== INDUSTRIAL MANUFACTURING — FINAL CTA (PREMIUM STRIP) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n  --line:rgba(49,59,134,.16);\n}\n\n.im-cta, .im-cta *{box-sizing:border-box;}\n.im-cta{\n  padding:84px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.08), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(49,59,134,.08), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.im-cta__inner{\n  max-width:1200px;\n  margin:0 auto;\n}\n\n.im-cta__bar{\n  border:1px solid rgba(49,59,134,.16);\n  border-radius:26px;\n  background:rgba(255,255,255,.86);\n  backdrop-filter:blur(10px);\n  box-shadow:0 22px 54px rgba(0,0,0,.08);\n  padding:28px 28px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:22px;\n}\n\n.im-cta__left{\n  min-width:0;\n  max-width:820px;\n}\n\n.im-cta__kicker{\n  margin:0 0 10px;\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n}\n\n.im-cta__title{\n  margin:0 0 10px;\n  font-size:clamp(26px,3.2vw,38px);\n  line-height:1.15;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.im-cta__text{\n  margin:0;\n  font-size:15.5px;\n  line-height:1.75;\n  color:var(--muted);\n}\n\n.im-cta__right{\n  flex:0 0 auto;\n  display:flex;\n  gap:12px;\n  flex-wrap:wrap;\n  justify-content:flex-end;\n}\n\n.im-cta__btn{\n  height:46px;\n  padding:0 18px;\n  border-radius:999px;\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:10px;\n  font-size:14px;\n  font-weight:800;\n  text-decoration:none;\n  transition:.2s ease;\n  white-space:nowrap;\n}\n\n.im-cta__btn--primary{\n  background:var(--violet);\n  color:#fff;\n  border:1px solid var(--violet);\n  box-shadow:0 12px 26px rgba(98,90,216,.22);\n}\n.im-cta__btn--primary:hover{\n  background:var(--accent);\n  border-color:var(--accent);\n  transform:translateY(-1px);\n}\n\n.im-cta__btn--ghost{\n  background:#fff;\n  color:var(--navy);\n  border:1px solid rgba(49,59,134,.22);\n}\n.im-cta__btn--ghost:hover{\n  background:rgba(49,59,134,.04);\n  transform:translateY(-1px);\n}\n\n/* small “signal” pill */\n.im-cta__pill{\n  display:inline-flex;\n  align-items:center;\n  gap:10px;\n  padding:9px 12px;\n  border-radius:999px;\n  border:1px solid rgba(49,59,134,.18);\n  background:rgba(49,59,134,.04);\n  color:var(--indigo);\n  font-weight:800;\n  font-size:12px;\n  margin-top:14px;\n}\n.im-cta__dot{\n  width:9px;height:9px;border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.10);\n}\n\n@media (max-width:980px){\n  .im-cta{padding:70px 18px;}\n  .im-cta__bar{padding:22px; flex-direction:column; align-items:flex-start;}\n  .im-cta__right{justify-content:flex-start;}\n}\n</style>\n\n<section class=\"im-cta\" id=\"industrial-cta\">\n  <div class=\"im-cta__inner\">\n\n    <div class=\"im-cta__bar\">\n      <div class=\"im-cta__left\">\n        <p class=\"im-cta__kicker\">Next steps</p>\n        <h2 class=\"im-cta__title\">Let’s Build the Next-Generation Healthcare  Enterprise</h2>\n        <p class=\"im-cta__text\">\n          From strategy and shared services to digital enablement, ESG, and operational excellence, we partner with healthcare organisations to deliver care systems that are efficient, compassionate, and built to last.\n        </p>\n\n        <div class=\"im-cta__pill\"><span class=\"im-cta__dot\" aria-hidden=\"true\"></span> Strategy • Ops • Digital • ESG</div>\n      </div>\n\n      <div class=\"im-cta__right\">\n        <a class=\"im-cta__btn im-cta__btn--ghost\" href=\"/contact-us\">Talk to us</a>\n        <a class=\"im-cta__btn im-cta__btn--primary\" href=\"/contact-us\">Request a consultation →</a>\n      </div>\n    </div>\n\n  </div>\n</section>";
